    public synchronized String voicePreference(){ensure();return settings.optString("voicePreference","");}
    public synchronized void voicePreference(String value){ensure();try{String v=value==null?"":value.trim();settings.put("voicePreference",v);if(v.isEmpty())settings.put("onlyPreferredVoice",false);else rememberVoiceLocked(v);write("settings",settings);}catch(Exception ignored){}}
    public synchronized boolean onlyPreferredVoice(){ensure();return settings.optBoolean("onlyPreferredVoice",false)&&!ApiRepository.voiceKey(voicePreference()).isEmpty();}
