    public synchronized String voiceFor(Anime a){ensure();try{JSONObject map=settings.optJSONObject("voiceByAnime");if(map==null||a==null)return "";String v=map.optString(voiceAnimeKey(a),"");if(v.isEmpty())v=map.optString(voiceAnimeAltKey(a),"");return v==null?"":v;}catch(Exception e){return "";}}
    public synchronized void setVoiceFor(Anime a,String value){ensure();if(a==null)return;try{JSONObject map=settings.optJSONObject("voiceByAnime");if(map==null)map=new JSONObject();String v=value==null?"":value.trim();String key=voiceAnimeKey(a);if(key.isEmpty())return;String alt=voiceAnimeAltKey(a);if(v.isEmpty()){map.remove(key);if(!alt.isEmpty())map.remove(alt);}else{if(map.length()>=60){java.util.Iterator<String> keys=map.keys();if(keys.hasNext())map.remove(keys.next());}map.put(key,v);if(!alt.isEmpty()&&!alt.equals(key))map.put(alt,v);}settings.put("voiceByAnime",map);write("settings",settings);}catch(Exception ignored){}}
    private static String voiceAnimeKey(Anime a){if(a==null)return "";if(a.malId>0)return "mal:"+a.malId;try{String k=a.key();return k==null?"":k;}catch(Exception e){return "";}}private static String voiceAnimeAltKey(Anime a){if(a==null||a.malId<=0)return "";try{String k=a.key();return k==null?"":k;}catch(Exception e){return "";}}
    public synchronized int todayStamp(){java.util.Calendar c=java.util.Calendar.getInstance();return c.get(java.util.Calendar.YEAR)*10000+(c.get(java.util.Calendar.MONTH)+1)*100+c.get(java.util.Calendar.DAY_OF_MONTH);}
    public synchronized Anime dailyHero(){ensure();try{JSONObject saved=settings.optJSONObject("dailyHero");if(saved==null||saved.optInt("day",-1)!=todayStamp())return null;Anime a=Anime.from(saved.optJSONObject("anime"));return Anime.valid(a)?a:null;}catch(Exception e){return null;}}
    public synchronized void saveDailyHero(Anime a){ensure();if(a==null||!Anime.valid(a))return;try{JSONObject saved=new JSONObject();saved.put("day",todayStamp());saved.put("anime",a.json());settings.put("dailyHero",saved);write("settings",settings);}catch(Exception ignored){}}
