    public synchronized ArrayList<String> favoriteVoices(){ensure();LinkedHashMap<String,String> map=new LinkedHashMap<>();String current=settings.optString("voicePreference","");String ck=ApiRepository.voiceKey(current);if(!ck.isEmpty())map.put(ck,ApiRepository.voiceTitle(current));JSONArray arr=settings.optJSONArray("favoriteVoices");for(int i=0;arr!=null&&i<arr.length();i++){String v=arr.optString(i,"");String title=ApiRepository.voiceTitle(v);String key=ApiRepository.voiceKey(title.isEmpty()?v:title);if(!key.isEmpty()&&!map.containsKey(key))map.put(key,title.isEmpty()?v:title);}return new ArrayList<>(map.values());}
    public synchronized void rememberVoice(String value){ensure();try{rememberVoiceLocked(value);write("settings",settings);}catch(Exception ignored){}}
    private void rememberVoiceLocked(String value)throws JSONException{if(value!=null&&value.startsWith("src:"))return;String title=ApiRepository.voiceTitle(value);if(title.isEmpty())title=value==null?"":value.trim();String key=ApiRepository.voiceKey(title);if(key.isEmpty())return;ArrayList<String> next=new ArrayList<>();next.add(title);JSONArray old=settings.optJSONArray("favoriteVoices");for(int i=0;old!=null&&i<old.length()&&next.size()<12;i++){String v=old.optString(i,"");String vk=ApiRepository.voiceKey(v);if(vk.isEmpty()||vk.equals(key))continue;next.add(ApiRepository.voiceTitle(v).isEmpty()?v:ApiRepository.voiceTitle(v));}JSONArray arr=new JSONArray();for(String v:next)arr.put(v);settings.put("favoriteVoices",arr);}
    public synchronized int voicePriority(String actual){ensure();String text=actual==null?"":actual;ArrayList<String> fav=favoriteVoices();for(int i=0;i<fav.size();i++)if(ApiRepository.voiceMatches(fav.get(i),text))return i;return -1;}
    public synchronized String favoriteVoiceSummary(){ArrayList<String> fav=favoriteVoices();if(fav.isEmpty())return "Авто";StringBuilder b=new StringBuilder();for(int i=0;i<fav.size()&&i<3;i++){if(b.length()>0)b.append(" → ");b.append(ApiRepository.voiceTitle(fav.get(i)));}if(fav.size()>3)b.append(" +").append(fav.size()-3);return b.toString();}
