    public synchronized void enqueueWatch(Anime a){ensure();if(!Anime.valid(a))return;try{JSONArray old=settings.optJSONArray("watchQueue"),next=new JSONArray();next.put(a.json());for(int i=0;old!=null&&i<old.length()&&next.length()<30;i++){Anime row=Anime.from(old.optJSONObject(i));if(Anime.valid(row)&&!row.key().equals(a.key()))next.put(row.json());}settings.put("watchQueue",next);write("settings",settings);}catch(Exception ignored){}}
