    public synchronized JSONObject stats(){ensure();try{JSONObject out=new JSONObject();int titles=0,episodes=0,finished=0;long seconds=0;HashMap<String,Integer> genres=new HashMap<>();Iterator<String> keys=history.keys();while(keys.hasNext()){JSONObject h=history.optJSONObject(keys.next());if(h==null)continue;Anime a=Anime.from(h.optJSONObject("release"));if(!Anime.valid(a))continue;titles++;episodes+=Math.max(1,(int)Math.floor(h.optDouble("episode",1)));seconds+=Math.max(0,h.optInt("time",0));if(a.episodes>0&&h.optDouble("episode",0)>=a.episodes)finished++;for(String g:a.genres)if(g!=null&&!g.trim().isEmpty())genres.put(g,genres.getOrDefault(g,0)+1);}ArrayList<Map.Entry<String,Integer>> gs=new ArrayList<>(genres.entrySet());gs.sort((a,b)->b.getValue()-a.getValue());JSONArray top=new JSONArray();for(int i=0;i<Math.min(5,gs.size());i++)top.put(gs.get(i).getKey());return out.put("titles",titles).put("episodes",episodes).put("seconds",seconds).put("finished",finished).put("favorites",favorites.length()).put("queue",watchQueue().size()).put("genres",top).put("ratings",ratedCount()).put("pins",pinnedCount()).put("hidden",hiddenCount()).put("rewatches",rewatchCount());}catch(Exception e){return new JSONObject();}}

    public synchronized int todayEpisodes(){ensure();Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);long start=c.getTimeInMillis();int n=0;Iterator<String> keys=history.keys();while(keys.hasNext()){JSONObject h=history.optJSONObject(keys.next());if(h!=null&&h.optLong("updated")>=start)n++;}return n;}
    public synchronized int ratedCount(){ensure();int n=0;Iterator<String> keys=settings.keys();while(keys.hasNext())if(keys.next().startsWith("rating:"))n++;return n;}
