    public synchronized void sourceEvent(String source,boolean ok,long ms,int episodes,int variants,int quality){ensure();String id=source==null||source.trim().isEmpty()?"yoru":source.trim();try{JSONObject all=settings.optJSONObject("sourceStats");if(all==null)all=new JSONObject();JSONObject row=all.optJSONObject(id);if(row==null)row=new JSONObject();row.put(ok?"ok":"fail",row.optInt(ok?"ok":"fail",0)+1);row.put("failRun",ok?0:Math.min(20,row.optInt("failRun",0)+1));row.put("last",System.currentTimeMillis());if(ok)row.put("lastOk",System.currentTimeMillis());else row.put("lastBad",System.currentTimeMillis());if(ms>0){long avg=row.optLong("avg",0);row.put("avg",avg<=0?ms:(avg*3+ms)/4);}if(episodes>0)row.put("episodes",Math.max(row.optInt("episodes",0),Math.min(episodes,10000)));if(variants>0)row.put("variants",Math.max(row.optInt("variants",0),Math.min(variants,10000)));if(quality>0)row.put("quality",Math.max(row.optInt("quality",0),Math.min(quality,4320)));all.put(id,row);ArrayList<String> keys=new ArrayList<>();Iterator<String> it=all.keys();while(it.hasNext())keys.add(it.next());if(keys.size()>36){final JSONObject stats=all;keys.sort((a,b)->Long.compare(stats.optJSONObject(a)==null?0:stats.optJSONObject(a).optLong("last",0),stats.optJSONObject(b)==null?0:stats.optJSONObject(b).optLong("last",0)));for(int i=0;i<keys.size()-36;i++)all.remove(keys.get(i));}settings.put("sourceStats",all);write("settings",settings);}catch(Exception ignored){}}
    public synchronized void replaceWatchQueue(List<Anime> rows){ensure();try{JSONArray next=new JSONArray();LinkedHashSet<String> seen=new LinkedHashSet<>();if(rows!=null)for(Anime a:rows){if(!Anime.valid(a)||!seen.add(a.key()))continue;next.put(a.json());if(next.length()>=30)break;}if(next.length()==0)settings.remove("watchQueue");else settings.put("watchQueue",next);write("settings",settings);}catch(Exception ignored){}}
    public synchronized ArrayList<Anime> mood(String mood){ensure();ArrayList<Anime> source=new ArrayList<>(favorites());source.addAll(recent());LinkedHashMap<String,Anime> out=new LinkedHashMap<>();String m=mood==null?"":mood.toLowerCase(Locale.ROOT);for(Anime a:source){String text=(a.title+" "+a.original+" "+a.type+" "+String.join(" ",a.genres)).toLowerCase(Locale.ROOT);boolean ok=m.contains("уют")&&(text.contains("повсед")||text.contains("роман")||text.contains("комед"))||m.contains("экшен")&&(text.contains("экшен")||text.contains("приключ"))||m.contains("корот")&&(a.episodes>0&&a.episodes<=13||text.contains("фильм"))||m.contains("роман")&&text.contains("роман");if(ok)out.put(a.key(),a);}return new ArrayList<>(out.values());}

    public synchronized String exportData(){ensure();try{return new JSONObject().put("format","yoru.android.v5").put("exportedAt",new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ssXXX",Locale.ROOT).format(new Date())).put("favorites",favorites).put("history",history).put("settings",settings).toString(2);}catch(Exception e){return "{}";}}
    public synchronized int importData(String input) throws Exception {ensure();if(input.length()>5*1024*1024)throw new Exception("Файл слишком большой");JSONObject root=new JSONObject(input);if(!root.optString("format").matches("yoru(?:\\.v[1-5]|\\.android\\.v[12345])"))throw new Exception("ÐÑÐ±ÐµÑÐ¸ÑÐµ ÑÐ°Ð¹Ð» ÐºÐ¾Ð»Ð»ÐµÐºÑÐ¸Ð¸ Yoru");int count=0;for(String name:new String[]{"favorites","history"}){JSONObject data=root.optJSONObject(name);if(data==null)continue;Iterator<String> keys=data.keys();while(keys.hasNext()){String k=keys.next();JSONObject item=data.optJSONObject(k);if(item==null)continue;Anime a=Anime.from(item.optJSONObject("release"));if(!Anime.valid(a)||!k.equals(a.key()))continue;if(name.equals("favorites")){String bucket=item.optString("bucket","planned");if(!Arrays.asList(BUCKETS).contains(bucket))bucket="planned";favorites.put(k,new JSONObject().put("release",a.json()).put("bucket",bucket).put("added",System.currentTimeMillis()).put("episodesSeen",Math.max(0,item.optInt("episodesSeen",a.episodes))).put("folders",item.optJSONArray("folders")==null?new JSONArray():item.optJSONArray("folders")));}else{double ep=item.optDouble("episode",1);if(!Double.isFinite(ep)||ep<0||ep>100000)continue;history.put(k,new JSONObject().put("release",a.json()).put("episode",ep).put("time",Math.min(100000,Math.max(0,item.optInt("time")))).put("duration",Math.min(100000,Math.max(0,item.optInt("duration")))).put("tracked",item.optBoolean("tracked",true)).put("updated",System.currentTimeMillis()).put("playerMode",item.optString("playerMode","")).put("dubbing",item.optString("dubbing","")));}count++;if(count>5000)break;}}JSONObject imported=root.optJSONObject("settings");if(imported!=null){HashSet<String> exact=new HashSet<>(Arrays.asList("fontScale","customFont","fontName","quality","playbackSpeed","autoNext","dataSaver","wifiDownloads","directOnly","liteMode","privateMode","spoilerSafe","hideSeen","autoSkipOpening","sleepTimer","originalTitles","watchQueue","sourceStats","voicePreference","onlyPreferredVoice","favoriteVoices","libraryFolders","libraryVersion","mobileDownloadsDefault"));Iterator<String> sk=imported.keys();while(sk.hasNext()){String key=sk.next();if(exact.contains(key)||key.startsWith("note:")||key.startsWith("rating:")||key.startsWith("tags:")||key.startsWith("pin:")||key.startsWith("hidden:")||key.startsWith("rewatch:"))settings.put(key,imported.opt(key));}}write("favorites",favorites);write("history",history);write("settings",settings);return count;}
