    public synchronized void addSearch(String query){ensure();String q=query==null?"":query.trim().replaceAll("\\s+"," ");if(q.length()<2)return;if(q.length()>80)q=q.substring(0,80).trim();try{ArrayList<String> rows=new ArrayList<>();rows.add(q);for(String old:searchHistory())if(!old.equalsIgnoreCase(q))rows.add(old);JSONArray arr=new JSONArray();for(int i=0;i<Math.min(14,rows.size());i++)arr.put(rows.get(i));settings.put("searchHistory",arr);write("settings",settings);}catch(Exception ignored){}}
